import java.time.Instant;import java.util.List;
public final class DeliveryDetailControl {
 public static void main(String[] args) {
  var x=new DeliveryDetailWindow.FrameStats("sampled-allocation-weight-bytes");
  x.currentAllocationClass="java.lang.Object[]";
  var stack=List.of("java.util.ArrayList.grow","org.opentaint.dataflow.bidi.store.MethodEdgeStore.add","org.opentaint.dataflow.bidi.ap.TrieOpsKt.subtract","org.opentaint.dataflow.bidi.ap.TrieOpsKt.subtract","org.opentaint.dataflow.bidi.engine.SubscriptionManager.onDelivery");
  x.add(Instant.EPOCH,stack,false,7L);x.add(Instant.EPOCH,stack,false,3L);
  if(x.events!=2||x.weight!=10||x.families.get("detail-subtract").events!=2||x.families.get("detail-subtract").weight!=10)throw new AssertionError("union count");
  if(x.families.get("summary-delivery").weight!=10||x.families.get("detail-point-storage").weight!=10)throw new AssertionError("intentional overlap");
  if(x.focusPaths.get("ArrayList.grow").size()!=1||x.focusPaths.get("ArrayList.grow").values().iterator().next().weight!=10)throw new AssertionError("stack merge");
  if(DeliveryDetailWindow.family("detail-candidate-snapshot","org.opentaint.dataflow.bidi.engine.SubscriptionManager.onDelivery"))throw new AssertionError("specific candidate false positive");
  if(!DeliveryDetailWindow.family("detail-candidate-snapshot","org.opentaint.dataflow.bidi.engine.CalleeSubscriptions$candidates$1.invokeSuspend"))throw new AssertionError("nested candidate missed");
  if(!DeliveryDetailWindow.family("detail-match-satisfying","org.opentaint.dataflow.bidi.engine.SubscriptionManagerKt.matches"))throw new AssertionError("match missed");
  System.out.println("PASS:2events10bytes;recursive family counted once per event;overlapping families retain10bytes each;one complete merged stack;candidate positive and negative controls");
 }
}

