/** Read-only, single-pass JFR aggregation. No expanded JSON export or dependencies. */
public final class DeliveryDetailWindow {
    static final int TOP_LIMIT = 1000;
    static final String VERSION = "selected-delivery-detail-v1";
    static final Set<String> SELECTED_TYPES = Set.of("jdk.ExecutionSample", "jdk.ObjectAllocationSample",
            "jdk.GCPhasePause", "jdk.GarbageCollection", "jdk.GCHeapSummary");

    static final class Window {
        final Instant start;
        final Instant end;
        Window(Instant start, Instant end) {
            if (end.isBefore(start)) throw new IllegalArgumentException("end precedes start");
            this.start = start;
            this.end = end;
        }
        boolean contains(Instant time) { return !time.isBefore(start) && time.isBefore(end); }
        long overlapNanos(Instant from, Instant to) {
            Instant lo = from.isBefore(start) ? start : from;
            Instant hi = to.isAfter(end) ? end : to;
            return hi.isAfter(lo) ? Duration.between(lo, hi).toNanos() : 0;
        }
    }

    static final String[] FAMILIES = {"demand-c2", "demand-c5", "demand-total", "static-entry-search", "static-pair-search", "static-call-graph", "call-pipeline", "summary-apply", "summary-match", "initial-admission", "rule-evaluation", "cleaners", "protection", "trie-work", "aliases", "nd-joins", "run1-static-pool", "joined-writer-binding", "AP-interning", "IR-storage", "Spring", "static-owner-eligibility", "static-label-selection", "static-direct-pairs", "static-mapped-geometry-precheck", "CFG-delivery", "base-relevance", "post-result-admission", "summary-delivery", "summary-subscribe", "summary-replay-records", "call-plan-build", "rule-condition-compile", "form-payload", "mark-metadata", "static-owner-index-build", "static-owner-index-query", "literal-identity", "identity-promotion", "compact-point-membership", "certified-admission", "mask-normalization", "persisted-replay", "caller-demand-lookup", "live-caller-accumulator", "current-summary-replay", "native-return-suffix", "generic-mask-merge", "detail-candidate-snapshot", "detail-match-satisfying", "detail-summary-parts", "detail-start-fact", "detail-summary-geometry", "detail-resume", "detail-flow-stages", "detail-post-output", "detail-point-storage", "detail-conclusion-groups", "detail-subtract", "detail-field-limit-wrapper", "detail-rule-micro-transfer", "detail-rule-predicate", "detail-selected-cleaners", "detail-alias-expansion", "detail-clean-chain"};
    static boolean family(String name, String f) {
        return switch (name) {
            case "persisted-replay" -> f.startsWith("org.opentaint.dataflow.bidi.engine.PersistedSummaryReplayKt.replayPersistedSummaries") || f.startsWith("org.opentaint.dataflow.bidi.engine.SubscriptionManager.replayRecords");
            case "caller-demand-lookup" -> f.startsWith("org.opentaint.dataflow.bidi.engine.RestrictedInitialEmissionKt.emitRestrictedInitials");
            case "live-caller-accumulator" -> f.startsWith("org.opentaint.dataflow.bidi.store.AddedFactAccumulator.add") || f.startsWith("org.opentaint.dataflow.bidi.engine.CalleeSubscriptions.admit");
            case "current-summary-replay" -> f.startsWith("org.opentaint.dataflow.bidi.engine.SubscriptionManager.replay") && !f.startsWith("org.opentaint.dataflow.bidi.engine.SubscriptionManager.replayRecords");
            case "native-return-suffix" -> f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodCallServices.applyRecord");
            case "generic-mask-merge" -> f.startsWith("org.opentaint.dataflow.bidi.ap.ApManager.mergeAddDelta") || f.startsWith("org.opentaint.dataflow.bidi.ap.TaintGroup.add");
            case "detail-candidate-snapshot" -> f.startsWith("org.opentaint.dataflow.bidi.engine.CalleeSubscriptions$candidates$") || f.startsWith("org.opentaint.dataflow.bidi.engine.CalleeSubscriptions.candidates") || f.startsWith("org.opentaint.dataflow.bidi.store.AddedFactAccumulator.snapshot");
            case "detail-match-satisfying" -> f.startsWith("org.opentaint.dataflow.bidi.engine.SubscriptionManagerKt.matches") || f.startsWith("org.opentaint.dataflow.bidi.ap.ApOps.satisfying");
            case "detail-summary-parts" -> f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodCallServices.summaryParts");
            case "detail-start-fact" -> f.startsWith("org.opentaint.dataflow.bidi.ap.ApOps.startFact") || f.startsWith("org.opentaint.dataflow.bidi.ap.DemandKt.initialFacts") || f.startsWith("org.opentaint.dataflow.bidi.ap.DemandKt.startFact");
            case "detail-summary-geometry" -> f.startsWith("org.opentaint.dataflow.bidi.ap.ApOps.applySummary") || f.startsWith("org.opentaint.dataflow.bidi.ap.SummaryKt.applySummaryPart") || f.startsWith("org.opentaint.dataflow.bidi.ap.SummaryKt.graftSummary");
