            case "detail-post-output" -> f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer.admitOutput") || f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer.completeOutput");
