            case "detail-selected-cleaners" -> f.startsWith("org.opentaint.dataflow.bidi.ap.CleanKt.") || f.startsWith("org.opentaint.dataflow.bidi.ap.FlowClean.") || f.startsWith("org.opentaint.dataflow.bidi.ap.TaintClean.") || f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodCallServices.cleanChain");
            case "detail-alias-expansion" -> f.contains(".alias.") || f.contains(".aliases.") || f.contains(".bidi.") && (f.contains(".Alias") || f.contains(".alias"));
