            case "aliases" -> f.contains(".alias.") || f.contains(".aliases.") || f.contains(".bidi.") && (f.contains(".Alias") || f.contains(".alias"));
            case "nd-joins" -> f.contains(".NdSummaryJoin") || f.contains(".KaryJoin") || f.contains(".ConjunctionStore") || f.contains(".RulePredicateStore") || f.contains(".Run1Origin");
            case "run1-static-pool" -> f.contains(".Run1StaticService") || f.contains(".StaticSupplies") || f.contains(".StaticBatch");
            case "joined-writer-binding" -> f.contains(".JoinedStaticWriterBinding") || f.contains(".CalleeSubscriptions.visitJoinedCandidates");
            case "AP-interning" -> f.contains(".bidi.ap.TrieInterner") || f.contains(".bidi.ap.TaintAlgebra.intern") || f.contains(".bidi.ap.ApManager.intern");
            case "IR-storage" -> f.startsWith("org.opentaint.ir.") || f.startsWith("jetbrains.exodus.");
            case "Spring" -> f.startsWith("org.opentaint.jvm.sast.project.spring.");
            case "static-owner-index-build" -> f.startsWith("org.opentaint.dataflow.bidi.store.FrozenOwnerVisibility$Builder");
            case "static-owner-index-query" -> f.startsWith("org.opentaint.dataflow.bidi.store.FrozenOwnerVisibility.contains");
            case "literal-identity" -> f.startsWith("org.opentaint.dataflow.bidi.ap.LiteralInitialImageKt.");
            case "identity-promotion" -> f.startsWith("org.opentaint.dataflow.bidi.store.MethodEdgeStore.promoteAndAdd");
            case "compact-point-membership" -> f.startsWith("org.opentaint.dataflow.bidi.store.MethodEdgeStore$ScalarPremiseRows.");
            case "certified-admission" -> f.startsWith("org.opentaint.dataflow.bidi.ap.GroupsKt.admittedTree");
            case "mask-normalization" -> f.startsWith("org.opentaint.dataflow.bidi.ap.FlowBackedProtectionKt.intersectTaintMask");
            case "static-owner-eligibility" -> f.startsWith("org.opentaint.dataflow.bidi.store.FrozenStaticCompletion$View.eligible");
            case "static-label-selection" -> f.startsWith("org.opentaint.dataflow.bidi.store.StaticOutputOrdinals") || f.startsWith("org.opentaint.dataflow.bidi.store.StaticSelectorIndexKt");
            case "static-direct-pairs" -> f.startsWith("org.opentaint.dataflow.bidi.store.FrozenStaticCompletion$View$pairs$") || f.startsWith("org.opentaint.dataflow.bidi.store.FrozenStaticCompletion$View.pairs");
            case "static-mapped-geometry-precheck" -> f.startsWith("org.opentaint.dataflow.bidi.store.StaticPairLookup.mappedRightMayEmit");
            case "CFG-delivery" -> f.startsWith("org.opentaint.dataflow.bidi.engine.CfgDeliveryCache.");
            case "base-relevance" -> f.startsWith("org.opentaint.dataflow.jvm.bidi.interp.JIRMethodForms.footprint") || f.startsWith("org.opentaint.dataflow.jvm.bidi.interp.JIRMethodForms.isBaseRelevant");
            case "post-result-admission" -> f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer.admitOutput") || f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer.completeOutput") || f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer.emitPackedAfter");
            case "summary-delivery" -> f.startsWith("org.opentaint.dataflow.bidi.engine.SubscriptionManager.onDelivery");
            case "summary-subscribe" -> f.startsWith("org.opentaint.dataflow.bidi.engine.SubscriptionManager.subscribe");
            case "summary-replay-records" -> f.startsWith("org.opentaint.dataflow.bidi.engine.SubscriptionManager.replayRecords");
            case "call-plan-build" -> f.startsWith("org.opentaint.dataflow.jvm.bidi.interp.JIRCallPlanBuilder.build");
            case "rule-condition-compile" -> f.startsWith("org.opentaint.dataflow.taint.SignedConditionNormalizer") || f.startsWith("org.opentaint.dataflow.jvm.bidi.interp.JIRRulePredicates");
            case "form-payload" -> f.startsWith("org.opentaint.dataflow.bidi.interp.FormsCache.payload");
