            default -> throw new IllegalArgumentException(name);
        };
    }
    static final class Count {
        long events;
        long weight;
        void add(long value) { events = Math.addExact(events, 1); weight = Math.addExact(weight, value); }
    }

    static final class FrameStats {
        final String weightUnit;
        long events, withStack, noStack, truncated, missingWeight, negativeWeight, zeroWeight;
        long weight, noStackWeight, frameOccurrences, uniqueFrameMemberships;
        Instant first, last;
        final Map<String, Count> leaf = new HashMap<>();
        final Map<String, Count> inclusive = new HashMap<>();
        final Map<String, Count> families = new HashMap<>();
        final Map<String, Count> leafFamilies = new HashMap<>();
        String currentAllocationClass = "<unavailable>";
        final Map<String, Map<String, Count>> focusPaths = new HashMap<>();
        final Map<String, Count> omittedFocusPaths = new HashMap<>();
        static final int FOCUS_DISTINCT_LIMIT = 1024;
        final Set<String> unique = new HashSet<>(); // scratch only; reset on every event
        FrameStats(String weightUnit) { this.weightUnit = weightUnit; }
        void add(Instant at, List<String> frames, boolean isTruncated, Long offeredWeight) {
            events = Math.addExact(events, 1);
            if (first == null || at.isBefore(first)) first = at;
            if (last == null || at.isAfter(last)) last = at;
            if (isTruncated) truncated = Math.addExact(truncated, 1);
            long value;
            if (offeredWeight == null) { missingWeight++; value = 0; }
            else if (offeredWeight < 0) { negativeWeight++; value = 0; }
            else { value = offeredWeight; if (value == 0) zeroWeight++; }
            weight = Math.addExact(weight, value);
            if (frames == null || frames.isEmpty()) {
                noStack++;
                noStackWeight = Math.addExact(noStackWeight, value);
                return;
            }
            if (weightUnit.equals("sampled-allocation-weight-bytes")) {
                String target = switch (frames.get(0)) {
                    case "java.util.ArrayList.grow" -> "ArrayList.grow";
                    case "java.lang.invoke.DirectMethodHandle.allocateInstance" -> "constructor-allocation";
                    case "org.opentaint.dataflow.bidi.ap.TrieOpsKt.subtract" -> "TrieOps.subtract";
                    default -> null;
                };
                if (target != null) {
                    Map<String, Count> paths = focusPaths.computeIfAbsent(target, ignored -> new HashMap<>());
                    String path = currentAllocationClass + "\n" + String.join("\n", frames);
                    Count existing = paths.get(path);
                    if (existing != null) existing.add(value);
                    else if (paths.size() < FOCUS_DISTINCT_LIMIT) {
                        Count count = new Count(); count.add(value); paths.put(path, count);
                    } else omittedFocusPaths.computeIfAbsent(target, ignored -> new Count()).add(value);
                }
            }
            withStack++;
            for (String name : FAMILIES) {
                if (family(name, frames.get(0))) leafFamilies.computeIfAbsent(name, ignored -> new Count()).add(value);
                for (String frame : frames) if (family(name, frame)) {
                    families.computeIfAbsent(name, ignored -> new Count()).add(value);
                    break;
                }
            }
            frameOccurrences = Math.addExact(frameOccurrences, frames.size());
            leaf.computeIfAbsent(frames.get(0), ignored -> new Count()).add(value);
            unique.clear();
            for (String frame : frames) {
                if (unique.add(frame)) {
                    inclusive.computeIfAbsent(frame, ignored -> new Count()).add(value);
                    uniqueFrameMemberships = Math.addExact(uniqueFrameMemberships, 1);
                }
            }
        }
        Map<String, Object> output() {
            return object("eventCount", events, "emptySampleWindow", events == 0, "weightUnit", weightUnit, "weight", weight,
                    "withStackEvents", withStack, "noStackEvents", noStack, "noStackWeight", noStackWeight,
                    "truncatedStackEvents", truncated, "missingWeightEvents", missingWeight,
                    "negativeWeightEvents", negativeWeight, "zeroWeightEvents", zeroWeight,
                    "frameOccurrences", frameOccurrences, "uniqueFrameMemberships", uniqueFrameMemberships,
                    "firstIncludedTimestamp", str(first), "lastIncludedTimestamp", str(last),
                    "leaf", table(leaf), "inclusive", table(inclusive), "familyInclusive", table(families), "familyLeaf", table(leafFamilies), "focusedAllocationStacks", focusedOutput());
        }
        Map<String, Object> focusedOutput() {
            Map<String, Object> out = new LinkedHashMap<>();
            for (String target : new java.util.TreeSet<>(focusPaths.keySet())) {
                Map<String, Count> values = focusPaths.get(target);
                List<Map.Entry<String, Count>> entries = new ArrayList<>(values.entrySet());
                entries.sort(Comparator.<Map.Entry<String, Count>>comparingLong(e -> e.getValue().weight).reversed());
                List<Object> rows = new ArrayList<>();
                for (int i = 0; i < Math.min(4, entries.size()); i++) {
                    Map.Entry<String, Count> entry = entries.get(i);
                    String[] parts = entry.getKey().split("\n");
                    List<String> stack = new ArrayList<>();
                    for (int j = parts.length - 1; j >= 1; j--) stack.add(parts[j]);
                    rows.add(object("allocatedClass", parts[0], "events", entry.getValue().events,
                            "sampledWeightBytes", entry.getValue().weight,
                            "rootToLeafFullRecordedStack", stack));
                }
                Count omitted = omittedFocusPaths.get(target);
                out.put(target, object("distinctRetainedPaths", values.size(), "distinctPathLimit", FOCUS_DISTINCT_LIMIT,
                        "unretainedEvents", omitted == null ? 0 : omitted.events,
                        "unretainedWeight", omitted == null ? 0 : omitted.weight,
                        "top4RetainedPaths", rows));
            }
            return out;
        }
        Map<String, Object> table(Map<String, Count> counts) {
            List<Map.Entry<String, Count>> entries = new ArrayList<>(counts.entrySet());
            entries.sort(Comparator.<Map.Entry<String, Count>>comparingLong(e -> e.getValue().weight).reversed()
                    .thenComparing(Comparator.<Map.Entry<String, Count>>comparingLong(e -> e.getValue().events).reversed())
                    .thenComparing(Map.Entry::getKey));
            List<Object> rows = new ArrayList<>();
            for (int i = 0; i < Math.min(entries.size(), TOP_LIMIT); i++) {
                Map.Entry<String, Count> entry = entries.get(i);
                Count count = entry.getValue();
                rows.add(object("frame", entry.getKey(), "events", count.events, "weight", count.weight,
                        "eventFraction", fraction(count.events, events), "weightFraction", fraction(count.weight, weight)));
            }
            return object("distinctFrames", entries.size(), "outputRowLimit", TOP_LIMIT,
                    "omittedRows", Math.max(0, entries.size() - TOP_LIMIT), "rows", rows);
        }
    }

    record Interval(Instant start, Instant end) {}
    static final class Durations {
        final Window window;
        long events, zeroDurationEvents, fullNanos, clippedNanos;
        final List<Interval> intervals = new ArrayList<>();
        final Map<String, Long> names = new HashMap<>();
        Durations(Window window) { this.window = window; }
        void add(Instant start, Instant end, String name) {
            long clipped = window.overlapNanos(start, end);
            if (clipped == 0 && !(start.equals(end) && window.contains(start))) return;
            events++;
            if (start.equals(end)) zeroDurationEvents++;
            fullNanos = Math.addExact(fullNanos, Duration.between(start, end).toNanos());
            clippedNanos = Math.addExact(clippedNanos, clipped);
            if (clipped > 0) intervals.add(new Interval(start.isBefore(window.start) ? window.start : start,
                    end.isAfter(window.end) ? window.end : end));
            names.merge(name, 1L, Math::addExact);
        }
        long unionNanos() {
            List<Interval> sorted = new ArrayList<>(intervals);
            sorted.sort(Comparator.comparing(Interval::start).thenComparing(Interval::end));
            long total = 0;
            Instant lo = null, hi = null;
            for (Interval item : sorted) {
                if (lo == null) { lo = item.start; hi = item.end; }
                else if (!item.start.isAfter(hi)) { if (item.end.isAfter(hi)) hi = item.end; }
                else { total = Math.addExact(total, Duration.between(lo, hi).toNanos()); lo = item.start; hi = item.end; }
            }
            return lo == null ? total : Math.addExact(total, Duration.between(lo, hi).toNanos());
        }
        Map<String, Object> output() {
            return object("intersectingEvents", events, "zeroDurationEvents", zeroDurationEvents,
                    "fullEventDurationNanos", fullNanos, "windowClippedDurationSumNanos", clippedNanos,
                    "windowIntervalUnionNanos", unionNanos(), "names", sorted(names));
        }
    }

    static final class HeapStats {
        long events, missingHeapUsed;
        Long min, max, firstValue, lastValue;
        Instant first, last;
        final Map<String, Long> byWhen = new HashMap<>();
        void add(Instant at, String when, Long heapUsed) {
            events++;
            byWhen.merge(when, 1L, Math::addExact);
            if (heapUsed == null) { missingHeapUsed++; return; }
            min = min == null ? heapUsed : Math.min(min, heapUsed);
            max = max == null ? heapUsed : Math.max(max, heapUsed);
            if (first == null || at.isBefore(first)) { first = at; firstValue = heapUsed; }
            if (last == null || at.isAfter(last)) { last = at; lastValue = heapUsed; }
        }
        Map<String, Object> output() {
            return object("events", events, "missingHeapUsedEvents", missingHeapUsed,
                    "byWhen", sorted(byWhen), "minHeapUsedBytes", min, "maxHeapUsedBytes", max,
                    "firstTimestamp", str(first), "firstHeapUsedBytes", firstValue,
                    "lastTimestamp", str(last), "lastHeapUsedBytes", lastValue);
        }
    }

    public static void main(String[] args) throws Exception {
        Map<String, String> options = options(args);
        Path recording = Path.of(required(options, "recording")).toRealPath();
        Path source = Path.of(required(options, "source")).toRealPath();
        Path output = Path.of(required(options, "output")).toAbsolutePath().normalize();
        Window window = new Window(Instant.parse(required(options, "start")), Instant.parse(required(options, "end")));
        if (Files.exists(output)) throw new IllegalArgumentException("Output exists: " + output);
        if (output.equals(recording) || output.equals(source)) throw new IllegalArgumentException("Output is an input");
        String claimedHash = options.get("recording-sha256");
        if (claimedHash != null && !claimedHash.matches("[0-9a-fA-F]{64}"))
            throw new IllegalArgumentException("recording-sha256 must have 64 hexadecimal characters");
        Map<String, Object> before = stat(recording);
        String sourceHash = sha256(Files.newInputStream(source));
        String classHash;
        try (InputStream input = DeliveryDetailWindow.class.getResourceAsStream("DeliveryDetailWindow.class")) {
            classHash = input == null ? null : sha256(input);
        }
        FrameStats execution = new FrameStats("execution-sample-events");
        FrameStats allocation = new FrameStats("sampled-allocation-weight-bytes");
        Durations pauses = new Durations(window), collections = new Durations(window);
        HeapStats heaps = new HeapStats();
        Map<String, Long> scanned = new HashMap<>(), startsInWindow = new HashMap<>();
        Map<String, Boolean> available = new LinkedHashMap<>();
        for (String name : new java.util.TreeSet<>(SELECTED_TYPES)) available.put(name, false);
        long scannedEvents = 0, includedStarts = 0;
        Instant firstRecorded = null, lastRecorded = null;
        try (RecordingFile file = new RecordingFile(recording)) {
            file.readEventTypes().forEach(type -> { if (available.containsKey(type.getName())) available.put(type.getName(), true); });
            while (file.hasMoreEvents()) {
                RecordedEvent event = file.readEvent();
                scannedEvents++;
                Instant at = event.getStartTime();
                if (firstRecorded == null || at.isBefore(firstRecorded)) firstRecorded = at;
                if (lastRecorded == null || at.isAfter(lastRecorded)) lastRecorded = at;
                boolean inside = window.contains(at);
                if (inside) includedStarts++;
                String type = event.getEventType().getName();
                if (!SELECTED_TYPES.contains(type)) continue;
                scanned.merge(type, 1L, Math::addExact);
                if (inside) startsInWindow.merge(type, 1L, Math::addExact);
                switch (type) {
                    case "jdk.ExecutionSample", "jdk.ObjectAllocationSample" -> {
                        if (!inside) break;
                        RecordedStackTrace stack = event.getStackTrace();
                        List<String> frames = frames(stack);
                        if (type.equals("jdk.ExecutionSample"))
                            execution.add(at, frames, stack != null && stack.isTruncated(), 1L);
                        else {
                            allocation.currentAllocationClass = event.hasField("objectClass") && event.getClass("objectClass") != null
                                    ? event.getClass("objectClass").getName() : "<unavailable>";
                            allocation.add(at, frames, stack != null && stack.isTruncated(), number(event, "weight"));
                        }
                    }
                    case "jdk.GCPhasePause" -> pauses.add(at, event.getEndTime(), text(event, "name"));
                    case "jdk.GarbageCollection" -> collections.add(at, event.getEndTime(),
                            text(event, "name") + " / " + text(event, "cause"));
                    case "jdk.GCHeapSummary" -> {
                        if (inside) heaps.add(at, text(event, "when"), number(event, "heapUsed"));
                    }
                    default -> throw new AssertionError(type);
                }
            }
        }
        Map<String, Object> after = stat(recording);
        if (!before.equals(after)) throw new IllegalStateException("Recording changed while reading; no output written");
        Map<String, Object> result = object("schema", VERSION,
                "reader", object("sourcePath", source.toString(), "sourceSha256", sourceHash,
                        "classResourceSha256", classHash, "javaVersion", System.getProperty("java.version"),
                        "compiledSourceBinding", "External javac receipt must bind source hash to class hash"),
                "recording", object("before", before, "after", after,
                        "externallySuppliedSha256", claimedHash == null ? null : claimedHash.toLowerCase(java.util.Locale.ROOT),
                        "sha256VerifiedByReader", false, "binding", "unchanged path/size/mtime/fileKey; optional digest is an external claim"),
                "window", object("startInclusive", window.start.toString(), "endExclusive", window.end.toString(),
                        "durationNanos", Duration.between(window.start, window.end).toNanos(),
                        "emptyWindow", window.start.equals(window.end), "allEventStartsInWindow", includedStarts,
                        "noObservedEventStarts", includedStarts == 0, "threadFilter", "none: all recorded threads",
                        "selectedEventTypesAvailable", available, "selectedEventStartsInWindow", sorted(startsInWindow)),
                "scan", object("allEvents", scannedEvents, "firstEventStart", str(firstRecorded),
                        "lastEventStart", str(lastRecorded), "selectedEventTypeCounts", sorted(scanned)),
                "executionSamples", execution.output(), "allocationSamples", allocation.output(),
                "gcPauses", pauses.output(), "garbageCollections", collections.output(), "gcHeapSummaries", heaps.output(),
                "interpretation", List.of(
                        "All input events are scanned once. Sample tables include event starts in [start,end). GC intervals are clipped to that window.",
                        "Execution tables use jdk.ExecutionSample only, include all recorded threads, and do not include jdk.NativeMethodSample. Event-type metadata presence does not prove continuous capture.",
                        "A leaf is the first JFR stack frame. Inclusive rows count one membership per normalized class.method per event, including recursive stacks only once.",
                        "Each table emits at most 1000 rows. Aggregation is exact over all distinct frames; omittedRows is output truncation, not stack truncation.",
                        "Inclusive rows overlap. Do not sum them, subtract overlapping families, or treat sampled events as operation counts or CPU seconds.",
                        "Family rows count one hit per event if any normalized frame matches the saved source predicate. Families overlap each other; their shares must not be summed. Family leaf rows classify only the first stack frame.",
                        "Allocation weight is sampled allocation bytes, including known weights from no-stack events. It is not retained heap, an exact allocation total, or object count.",
                        "Missing or negative allocation weights contribute zero weight but remain event counts and explicit counters. Zero-weight events remain counts.",
                        "Pause duration sums may overlap; interval unions remove overlap within each GC event family. Do not add GC families together.",
                        "GC heap summaries are point-in-time JVM heapUsed observations, not retained-owner measurements. A missing/empty event window is not zero analyzer work.",
                        "Recorded class.method names merge overloads. No native-profile denominator or exact source-line attribution is asserted."));
        byte[] bytes = (json(result) + "\n").getBytes(StandardCharsets.UTF_8);
        Files.write(output, bytes, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
        System.out.println("CLOSED " + output + " bytes=" + bytes.length + " sha256=" + sha256(Files.newInputStream(output)));
    }

    static List<String> frames(RecordedStackTrace stack) {
        if (stack == null) return null;
        List<String> result = new ArrayList<>(stack.getFrames().size());
        for (RecordedFrame frame : stack.getFrames()) {
            RecordedMethod method = frame.getMethod();
            result.add(method == null ? "<unresolved-frame:" + frame.getType() + ">"
                    : method.getType().getName() + "." + method.getName());
        }
        return result;
    }
    static Long number(RecordedObject event, String field) {
        if (!event.hasField(field)) return null;
        Object value = event.getValue(field);
        return value instanceof Number number ? number.longValue() : null;
    }
    static String text(RecordedObject event, String field) {
        if (!event.hasField(field)) return "<missing>";
        Object value = event.getValue(field);
        return value == null ? "<null>" : value.toString();
    }
    static Map<String, String> options(String[] args) {
        Set<String> accepted = Set.of("recording", "source", "output", "start", "end", "recording-sha256");
        Map<String, String> values = new HashMap<>();
        for (int i = 0; i < args.length; i += 2) {
            if (!args[i].startsWith("--") || i + 1 == args.length) throw new IllegalArgumentException("Expected --key value pairs");
            String key = args[i].substring(2);
            if (!accepted.contains(key) || values.putIfAbsent(key, args[i + 1]) != null)
                throw new IllegalArgumentException("Unknown or duplicate option: " + key);
        }
        return values;
    }
    static String required(Map<String, String> options, String key) {
        String value = options.get(key);
        if (value == null) throw new IllegalArgumentException("Required --" + key);
        return value;
    }
    static Map<String, Object> stat(Path path) throws Exception {
        BasicFileAttributes attrs = Files.readAttributes(path, BasicFileAttributes.class);
        return object("path", path.toString(), "sizeBytes", attrs.size(),
                "modified", attrs.lastModifiedTime().toString(), "fileKey", String.valueOf(attrs.fileKey()));
    }
    static String sha256(InputStream input) throws Exception {
        try (input) {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] buffer = new byte[65536];
            int size;
            while ((size = input.read(buffer)) != -1) digest.update(buffer, 0, size);
            return java.util.HexFormat.of().formatHex(digest.digest());
        }
    }
    static Object fraction(long value, long total) { return total == 0 ? null : (double) value / total; }
    static String str(Instant value) { return value == null ? null : value.toString(); }
    static Map<String, Object> object(Object... pairs) {
        if (pairs.length % 2 != 0) throw new IllegalArgumentException("Odd key/value list");
        Map<String, Object> result = new LinkedHashMap<>();
        for (int i = 0; i < pairs.length; i += 2) result.put((String) pairs[i], pairs[i + 1]);
        return result;
    }
    static Map<String, Long> sorted(Map<String, Long> input) { return new java.util.TreeMap<>(input); }
    static String json(Object value) {
        if (value == null) return "null";
        if (value instanceof Number || value instanceof Boolean) return value.toString();
        if (value instanceof String string) return quote(string);
        if (value instanceof Map<?, ?> map) {
            StringBuilder out = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                if (!first) out.append(','); first = false;
                out.append(quote(entry.getKey().toString())).append(':').append(json(entry.getValue()));
            }
            return out.append('}').toString();
        }
        if (value instanceof Iterable<?> items) {
            StringBuilder out = new StringBuilder("[");
            boolean first = true;
            for (Object item : items) { if (!first) out.append(','); first = false; out.append(json(item)); }
            return out.append(']').toString();
        }
        throw new IllegalArgumentException("Cannot encode " + value.getClass());
    }
    static String quote(String value) {
        StringBuilder out = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            switch (ch) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> { if (ch < 32) out.append(String.format("\\u%04x", (int) ch)); else out.append(ch); }
            }
        }
        return out.append('"').toString();
    }
}

