#!/usr/bin/env python3
"""Run only bounded offline readers once each selected project has closed."""
from pathlib import Path
import datetime as dt,json,subprocess,sys,time,traceback,os
ROOT=Path(__file__).resolve().parent.parent
TOOLS=ROOT/'analysis-tools'
PROJECTS=['OWASP','conductor','thingsboard','Stirling-PDF']
STATE=ROOT/'profile-analysis/watcher-state.json'

def save(value):
 value['utc']=dt.datetime.now(dt.timezone.utc).isoformat()
 tmp=STATE.with_suffix('.writing');tmp.write_text(json.dumps(value,indent=2)+'\n');os.replace(tmp,STATE)
def run(args):
 result=subprocess.run(['nice','-n','15',sys.executable,*map(str,args)],capture_output=True,text=True,timeout=900)
 print(result.stdout,flush=True)
 if result.returncode:raise RuntimeError({'args':list(map(str,args)),'returncode':result.returncode,'stderr':result.stderr})

def main():
 state={'state':'LIVE','pid':os.getpid(),'runtime':json.loads((ROOT/'pin.json').read_text())['runtime'],'projects':{}}
 for project in PROJECTS:
  if (ROOT/'profile-analysis'/(project+'-profile-summary.json')).exists():
   state['projects'][project]={'state':'COMPLETE_EXISTING'}
 save(state)
 while len(state['projects'])<len(PROJECTS):
  for project in PROJECTS:
   if project in state['projects']:continue
   d=ROOT/'projects'/project/'bidi';summary=d/'summary.json';process=d/'analyzer-process.json'
   if not summary.exists() or not process.exists():continue
   pid=json.loads(process.read_text())['pid']
   if Path('/proc',str(pid),'exe').exists():continue
   info=json.loads(summary.read_text())
   labels={key:info[value] for key,value in [('latestReachedRun','latest_bidi_iteration'),('latestCompleteRun','latest_complete_bidi_iteration'),('latestAcceptedForwardRun','latest_accepted_forward_report')]}
   state['projects'][project]={'state':'READING',**labels};save(state)
   try:
    run([TOOLS/'extract_envelope.py','--project',project,'--recording','continuous'])
    if (d/'run1.jfr').exists() and info.get('run1_recording',{}).get('returncode')==0:
     run([TOOLS/'extract_envelope.py','--project',project,'--recording','run1'])
     run([TOOLS/'extract_selected_jfr.py','--project',project,'--recording','run1'])
     log=json.loads((ROOT/'phase-evidence.json').read_text())
     rows=next(x for x in log['projects'] if x['project']==project)['iterations']
     later=[str(x['run']) for x in rows if x['run']!=1]
     if later:run([TOOLS/'extract_selected_jfr.py','--project',project,'--recording','continuous','--runs',*later])
    else:run([TOOLS/'extract_selected_jfr.py','--project',project,'--recording','continuous'])
    closed=[name for name in PROJECTS if (ROOT/'projects'/name/'bidi/summary.json').exists() and not Path('/proc',str(json.loads((ROOT/'projects'/name/'bidi/analyzer-process.json').read_text())['pid']),'exe').exists()]
    run([TOOLS/'closed_cpu_selected.py','--projects',*closed])
    run([TOOLS/'summarize_current_jfr.py','--project',project])
    run([ROOT/'profile-analysis/summarize_profiles.py',project])
    state['projects'][project]={'state':'COMPLETE',**labels}
    print('PROJECT_PROFILE_COMPLETE',project,labels,flush=True)
   except BaseException as error:
    state['projects'][project]={'state':'FAILED',**labels,'error':repr(error),'traceback':traceback.format_exc()}
    print('PROJECT_PROFILE_FAILED',project,repr(error),flush=True)
   save(state)
  if len(state['projects'])<len(PROJECTS):time.sleep(10)
 state['state']='COMPLETE' if all(x['state'].startswith('COMPLETE') for x in state['projects'].values()) else 'FAILED';save(state)
 print(state['state'],flush=True)
if __name__=='__main__':main()

