    private boolean emptyLeaf(IObject leaf,boolean flow) throws Exception {
        return flow?en(leaf).equals("NONE"):marks(obj(f(leaf,"exact"))).length==0&&marks(obj(f(leaf,"any"))).length==0;
    }
    private static boolean one(int[] values,int expected){return values.length==1&&values[0]==expected;}
    private boolean singlePath(IObject root,Initial initial,boolean flow) throws Exception {
        IObject node=root;
        for(int depth=0;;depth++) {
            IObject leaf=obj(f(node,"leaf"));long[] children=refs(obj(f(node,"childData")));
            if(depth==initial.path.length) {
                if(children.length!=0)return false;
                if(flow)return en(leaf).equals("LEAF");
                int[] ex=marks(obj(f(leaf,"exact"))),any=marks(obj(f(leaf,"any")));
                return initial.tail.equals("EXACT")?one(ex,initial.atom)&&any.length==0:ex.length==0&&one(any,initial.atom);
            }
            if(!emptyLeaf(leaf,flow)||children.length!=1)return false;
            int[] access=ints(obj(f(node,"accessorData")));
            if(access.length!=1||access[0]!=initial.path[depth])return false;
            node=at(children[0]);
        }
    }
    /** Empty string means exact initial fact image, independent of NORMAL/DEMAND and protection. */
    private String identityReason(Initial initial,IObject fact) throws Exception {
        if(initial==null)return "ND_PREMISE";
        boolean flow=cls(fact).equals(AP+"FlowTree");
        if(!cls(fact).equals(AP+"TaintTree")&&!flow)throw new IllegalStateException("Unexpected fact: "+cls(fact));
        if(!initial.kind.equals(flow?"FLOW":"TAINT"))return "KIND";
        if(!initial.base.equals(base(obj(f(fact,"base")))))return "BASE";
        int[] expectedExclusion=!flow&&(initial.tail.equals("EXACT")||initial.tail.equals("ANY"))?new int[0]:initial.exclusion;
        if(!Arrays.equals(expectedExclusion,exclusion(obj(f(fact,"exclusion")))))return "FIELD_EXCLUSION";
        String expectedTail=!flow&&initial.tail.equals("EXACT")?"ANY_TAINT":initial.tail;
        if(!expectedTail.equals(en(f(fact,flow?"tail":"anyTail"))))return "TAIL";
        if(flow&&marks(obj(f(obj(f(fact,"markExclusion")),"atoms"))).length!=0)return "MARK_EXCLUSION";
        if(!singlePath(obj(f(fact,"root")),initial,flow))return "PATH_OR_MARK_SET";
        if(!flow){IObject mask=obj(f(fact,"nonSubsumable"));if(mask!=null&&!singlePath(mask,initial,false))return "UNSUPPORTED_PROTECTION";}
        return "";
    }

    private static final class Cell {
        long headers,identity,protectedIdentity,control;
    }
    private Cell cell(IObject group,Initial initial,String scope,Map<String,Long> stats,
                      Map<String,Long> reasons,SetInt uniqueHeaders,SetInt uniqueRoots) throws Exception {
        Cell c=new Cell();boolean[] reach=(boolean[])((IPrimitiveArray)f(group,"reach")).getValueArray();
        for(boolean bit:reach)if(bit)c.control++;
        for(String kind:new String[]{"flow","taint"})for(Map.Entry<IObject,IObject> e:map(obj(f(group,kind)))) {
            long[] layers=refs(obj(f(e.getValue(),"trees")));
            if(layers.length!=2)throw new IllegalStateException("Unexpected layer count");
            for(long listAddress:layers)for(int factId:contents(at(listAddress))) {
                IObject fact=snapshot.getObject(factId);c.headers++;
                String key=scope+"=>"+family(base(obj(f(fact,"base"))))+"/"+kind.toUpperCase(Locale.ROOT)+"/"+en(f(fact,"layer"));
                inc(stats,"headers/"+key,1);inc(stats,"logicalHeaderShallowBytes/"+key,fact.getUsedHeapSize());
                String why=identityReason(initial,fact);
                if(why.isEmpty()) {
                    c.identity++;inc(stats,"literalIdentityHeaders/"+key,1);
                    if(kind.equals("taint")&&f(fact,"nonSubsumable")!=null){c.protectedIdentity++;inc(stats,"protectedIdentityHeaders/"+key,1);}
                    if(uniqueHeaders.add(factId))inc(stats,"physicalLiteralIdentityHeaderShallowBytes",fact.getUsedHeapSize());
                    uniqueRoots.add(obj(f(fact,"root")).getObjectId());
                } else inc(reasons,scope+"/"+why,1);
                tick();
            }
        }
        return c;
    }
    private static BitSet decodeBits(long[] words,int used) {
        if(used<0||used>words.length)throw new IllegalStateException("Invalid BitSet wordsInUse");
        if(used>0&&words[used-1]==0)throw new IllegalStateException("BitSet trailing used word is zero");
        for(int i=used;i<words.length;i++)if(words[i]!=0)throw new IllegalStateException("BitSet nonzero unused word");
        return BitSet.valueOf(Arrays.copyOf(words,used));
    }
    private BitSet bits(IObject bitset,Map<String,Long> stats,String scope) throws Exception {
        if(bitset==null)return new BitSet();
        if(!cls(bitset).equals("java.util.BitSet"))throw new IllegalStateException("Unknown point bits "+cls(bitset));
        IPrimitiveArray array=(IPrimitiveArray)f(bitset,"words");
        if(array==null)throw new IllegalStateException("BitSet words are null");
        long[] values=(long[])array.getValueArray();int used=(int)number(f(bitset,"wordsInUse"));
        inc(stats,"bitSets/"+scope,1);inc(stats,"bitWordsCapacity/"+scope,values.length);
        inc(stats,"bitSetShallowBytes/"+scope,bitset.getUsedHeapSize());
        inc(stats,"bitArrayShallowBytes/"+scope,array.getUsedHeapSize());
        return decodeBits(values,used);
    }
    private static long compactCount(BitSet normal,BitSet demand,BitSet protectedNormal,
                                     BitSet protectedDemand,int size) {
        for(BitSet bits:new BitSet[]{normal,demand,protectedNormal,protectedDemand})
            if(bits.length()>size)throw new IllegalStateException("Point bit exceeds method size");
        BitSet invalid=(BitSet)protectedNormal.clone();invalid.andNot(normal);
        if(!invalid.isEmpty())throw new IllegalStateException("Protected NORMAL point is absent");
        invalid=(BitSet)protectedDemand.clone();invalid.andNot(demand);
        if(!invalid.isEmpty())throw new IllegalStateException("Protected DEMAND point is absent");
        BitSet union=(BitSet)normal.clone();union.or(demand);return union.cardinality();
    }
    private static void fullPointDisjoint(BitSet normal,BitSet demand,int index) {
        if(normal.get(index)||demand.get(index))throw new IllegalStateException("Point is both compact and full");
    }
    private void methods() throws Exception {
        Map<String,Long> stats=new TreeMap<>(),reasons=new TreeMap<>();
        SetInt uniqueIdentityHeaders=new SetInt(),uniqueIdentityRoots=new SetInt();
        Top top=new Top("occupiedCells",50),staticTop=new Top("staticCompactPoints",50);
        int[] stores=ids(ST+"MethodEdgeStore");long scalar=0,packed=0,underConstruction=0;
        for(int storeId:stores) {
            IObject store=snapshot.getObject(storeId);if(f(store,"packed")!=null){packed++;continue;}
            IObject groups=obj(f(store,"groups"));if(groups==null){underConstruction++;continue;}scalar++;
            int size=(int)number(f(store,"size"));
            long occupied=0,compact=0,identities=0,staticCompact=0,staticPremises=0,headers=0,full=0;
            SetInt staticSites=new SetInt();
            for(Map.Entry<IObject,IObject> e:map(groups)) {
                IObject premise=e.getKey();Initial initial=cls(premise).equals(AP+"InitialAp")?new Initial(premise):null;
                String scope=initial==null?premiseScope(premise):initial.scope;
                IObject rows=e.getValue();
                if(!cls(rows).equals(ST+"MethodEdgeStore$ScalarPremiseRows"))
                    throw new IllegalStateException("Unknown scalar rows shape: "+cls(rows));
                IObject storedInitial=obj(f(rows,"initial"));
                boolean nonzeroInitial=initial!=null&&!initial.base.equals("Zero");
                if(id(storedInitial)!=(nonzeroInitial?premise.getObjectId():-1))
                    throw new IllegalStateException("Scalar owner initial does not match premise");
                inc(stats,"scalarPremiseRows/"+scope,1);inc(stats,"scalarRowsShallowBytes/"+scope,rows.getUsedHeapSize());
                BitSet normal=bits(obj(f(rows,"normal")),stats,scope),demand=bits(obj(f(rows,"demand")),stats,scope);
                BitSet pn=bits(obj(f(rows,"protectedNormal")),stats,scope),pd=bits(obj(f(rows,"protectedDemand")),stats,scope);
                long n=compactCount(normal,demand,pn,pd,size);
                if(!nonzeroInitial&&n!=0)throw new IllegalStateException("Unsupported premise owns compact points");
                if(initial!=null&&initial.kind.equals("FLOW")&&(!pn.isEmpty()||!pd.isEmpty()))
                    throw new IllegalStateException("FLOW compact point is protected");
                occupied+=n;compact+=n;inc(stats,"compactPoints/"+scope,n);
                inc(stats,"compactNormal/"+scope,normal.cardinality());inc(stats,"compactDemand/"+scope,demand.cardinality());
                inc(stats,"protectedNormal/"+scope,pn.cardinality());inc(stats,"protectedDemand/"+scope,pd.cardinality());
                if(initial!=null&&initial.base.equals("ClassStatic")) {
                    staticPremises++;staticCompact+=n;
                    for(int i=normal.nextSetBit(0);i>=0;i=normal.nextSetBit(i+1))staticSites.add(i);
                    for(int i=demand.nextSetBit(0);i>=0;i=demand.nextSetBit(i+1))staticSites.add(i);
                }
                IObjectArray array=(IObjectArray)f(rows,"full");
                if(array!=null) {
                    if(array.getLength()!=size)throw new IllegalStateException("Full scalar array size mismatch");
                    inc(stats,"fullArrays/"+scope,1);inc(stats,"fullArraySlots/"+scope,array.getLength());
                    inc(stats,"fullArrayShallowBytes/"+scope,array.getUsedHeapSize());
                    int atIndex=0;
                    for(long address:array.getReferenceArray()) {
                        if(address!=0) {
                            fullPointDisjoint(normal,demand,atIndex);
                            occupied++;full++;inc(stats,"fullCells/"+scope,1);IObject group=at(address);
                            if(!cls(group).equals(AP+"ConclusionGroup"))throw new IllegalStateException("Unknown full group "+cls(group));
                            inc(stats,"logicalConclusionGroupShallowBytes/"+scope,group.getUsedHeapSize());
                            Cell c=cell(group,initial,scope,stats,reasons,uniqueIdentityHeaders,uniqueIdentityRoots);headers+=c.headers;
                            if(c.identity>0)inc(stats,"fullCellsWithLiteralIdentity/"+scope,1);
                            if(c.identity>0&&c.identity==c.headers&&c.control==0) {
                                identities++;inc(stats,"fullLiteralIdentityOnlyCells/"+scope,1);
                            } else inc(stats,"fullOtherOrMixedCells/"+scope,1);
                        }
                        atIndex++;
                    }
                }
                tick();
            }
            long reachPremises=0,reachMemberships=0;
            for(Map.Entry<IObject,IObject> e:map(obj(f(store,"reach")))) {
                String scope=premiseScope(e.getKey());reachPremises++;
                for(long address:refs(e.getValue())) {
                    IObject set=at(address);BitSet decoded=bits(set,stats,"REACH/"+scope);
                    if(decoded.length()>size)throw new IllegalStateException("REACH bit exceeds method size");
                    long n=decoded.cardinality();reachMemberships+=n;inc(stats,"reachPointMemberships/"+scope,n);
                }
            }
            inc(stats,"reachPremiseArrays",reachPremises);inc(stats,"reachPointMemberships",reachMemberships);
            inc(stats,"occupiedCells",occupied);inc(stats,"compactPoints",compact);inc(stats,"fullCells",full);
            IObject key=obj(f(store,"method"));Map<String,Object> row=new LinkedHashMap<>();
            row.put("storeId",storeId);row.put("methodKeyId",key.getObjectId());row.put("method",keyName(key));
            row.put("occupiedCells",occupied);row.put("compactPoints",compact);row.put("fullCells",full);
            row.put("fullHeaderOccurrences",headers);row.put("fullIdentityOnlyCells",identities);
            row.put("staticPremises",staticPremises);row.put("staticCompactPoints",staticCompact);
            row.put("staticCompactStatementIndices",staticSites.size());row.put("staticPremiseTimesCompactSites",staticPremises*staticSites.size());
            top.add(row);staticTop.add(row);tick();
        }
        Map<String,Object> out=new LinkedHashMap<>();out.put("stores",stores.length);out.put("scalarStores",scalar);
        out.put("packedStoresSkipped",packed);out.put("underConstructionStores",underConstruction);out.put("counts",stats);
        out.put("nonIdentityReasonsByFullHeaderOccurrence",reasons);out.put("physicalFullLiteralIdentityHeaders",uniqueIdentityHeaders.size());
        out.put("physicalFullLiteralIdentityTrieRoots",uniqueIdentityRoots.size());out.put("topOccupiedCells",top.get());out.put("topStaticCompactCells",staticTop.get());
        out.put("definition","Occupied scalar cells = unique compact (premise,S) points plus full cells. NORMAL/DEMAND and protection counts are layer memberships. Compact points contain no conclusion headers. Full literal-identity counts are exact initial images; mixed trees do not count.");
        result.put("methodStores",out);
    }

