                if(address==0)throw new IllegalStateException("Null owner word row");
                IPrimitiveArray row=(IPrimitiveArray)at(address);long[] values=(long[])row.getValueArray();
                if(values.length!=wordCount)throw new IllegalStateException("Owner row width mismatch");
                for(long value:values)bits+=Long.bitCount(value);
