    private void deliveryBatch(IObject list,int ownerId,int calleeId,String source,DeliveryTotals total) throws Exception {
        if(list==null)throw new IllegalStateException("Null publication batch in "+source);
        boolean firstList=total.lists.add(list.getObjectId());
        int[] entries=contents(list); // Extractor verifies exact live size; never use capacity.
        inc(total.counts,"batches",1);inc(total.lengths,Integer.toString(entries.length),1);
        inc(total.counts,"rawPublicationOccurrences",entries.length);
        if(firstList)inc(total.counts,"uniquePhysicalListMemberships",entries.length);
        Map<TypedLane,Integer> typed=new HashMap<>();Map<AnnotatedLane,Integer> annotated=new HashMap<>();
        SetInt withinBatchPublications=new SetInt();long eligible=0,excluded=0,protectedOccurrences=0;
        Map<String,Long> excludedKinds=new TreeMap<>();
        for(int publicationId:entries) {
            tick();
            IObject pub=snapshot.getObject(publicationId);
            if(!cls(pub).equals(EN+"Publication"))throw new IllegalStateException("Unknown publication payload "+cls(pub));
            total.publications.add(publicationId);
            if(!withinBatchPublications.add(publicationId))inc(total.counts,"repeatedPublicationObjectOccurrencesWithinBatch",1);
            IObject premise=obj(f(pub,"premise")),fact=obj(f(pub,"conclusion"));
            if(premise==null||fact==null)throw new IllegalStateException("Null publication premise/conclusion");
            total.facts.add(fact.getObjectId());
            if(cls(fact).equals(AP+"TaintTree")) {
                IObject mask=obj(f(fact,"nonSubsumable"));if(mask!=null){total.masks.add(mask.getObjectId());protectedOccurrences++;}
            } else if(!cls(fact).equals(AP+"FlowTree")&&!cls(fact).equals(AP+"Reach"))
                throw new IllegalStateException("Unknown publication conclusion "+cls(fact));
            String skip=null;
            if(cls(premise).equals(AP+"PremiseSet"))skip="ND-premise";
            else if(!cls(premise).equals(AP+"InitialAp"))throw new IllegalStateException("Unknown publication premise "+cls(premise));
            else if(base(obj(f(premise,"base"))).equals("Zero"))skip="ZERO-premise";
            else if(cls(fact).equals(AP+"Reach"))skip="REACH-conclusion";
            if(skip!=null){excluded++;inc(excludedKinds,skip,1);continue;}
            TypedLane key=lane(premise.getObjectId(),fact);
            IObject mask=cls(fact).equals(AP+"TaintTree")?obj(f(fact,"nonSubsumable")):null;
            typed.merge(key,1,Math::addExact);annotated.merge(new AnnotatedLane(key,id(mask)),1,Math::addExact);
            eligible++;
        }
        if(eligible+excluded!=entries.length)throw new IllegalStateException("Batch census does not partition publications");
        long ordinarySurplus=eligible-typed.size(),annotatedSurplus=eligible-annotated.size();
        inc(total.counts,"eligiblePublicationOccurrences",eligible);inc(total.counts,"excludedPublicationOccurrences",excluded);
        inc(total.counts,"protectedPublicationOccurrences",protectedOccurrences);
        inc(total.counts,"potentialOrdinaryHeaderLanesSummedPerBatch",typed.size());
        inc(total.counts,"potentialAnnotationSeparatedLanesSummedPerBatch",annotated.size());
        inc(total.counts,"potentialOrdinaryHeaderSurplus",ordinarySurplus);
        inc(total.counts,"potentialAnnotationSeparatedSurplus",annotatedSurplus);
        for(Map.Entry<String,Long> entry:excludedKinds.entrySet())inc(total.counts,"excluded/"+entry.getKey(),entry.getValue());
        long repeatedLanes=annotated.values().stream().filter(n->n>1).count();
        inc(total.counts,"potentialAnnotationSeparatedLanesWithRepeats",repeatedLanes);
        Map<String,Object> row=new LinkedHashMap<>();row.put("source",source);row.put("ownerObjectId",ownerId);
        row.put("calleeOrActorMethodKeyId",calleeId);row.put("publicationListObjectId",list.getObjectId());
        row.put("rawPublicationOccurrences",entries.length);row.put("uniquePublicationObjectsWithinBatch",withinBatchPublications.size());
        row.put("eligiblePublicationOccurrences",eligible);row.put("excluded",excludedKinds);
        row.put("potentialOrdinaryHeaderLanes",typed.size());row.put("potentialAnnotationSeparatedLanes",annotated.size());
        row.put("potentialAnnotatedSurplus",annotatedSurplus);row.put("protectedPublicationOccurrences",protectedOccurrences);
        total.top.add(row);tick();
    }
    private Map<String,Object> deliveryResult(DeliveryTotals total) {
        Map<String,Object> result=new LinkedHashMap<>();result.put("counts",total.counts);
        result.put("rawBatchLengthHistogram",total.lengths);result.put("uniquePhysicalLists",total.lists.size());
        result.put("uniquePhysicalPublicationObjects",total.publications.size());result.put("uniquePhysicalConclusionObjects",total.facts.size());
        result.put("uniquePhysicalProtectionMasks",total.masks.size());result.put("topPotentialBatches",total.top.get());
        long eligible=total.counts.getOrDefault("eligiblePublicationOccurrences",0L);
        long lanes=total.counts.getOrDefault("potentialAnnotationSeparatedLanesSummedPerBatch",0L);
        result.put("eligibleOccurrencesPerPotentialAnnotationSeparatedLane",lanes==0?null:(double)eligible/lanes);
        long raw=total.counts.getOrDefault("rawPublicationOccurrences",0L);
        long excluded=total.counts.getOrDefault("excludedPublicationOccurrences",0L);
        result.put("potentialPackedPublicationOccurrencesWithExcludedUnchanged",lanes+excluded);
