    private void arrivals() throws Exception {
        Collection<IClass> schema=snapshot.getClassesByName(EN+"RunEvent$LinkIn",false);
        Collection<IClass> initialSchema=snapshot.getClassesByName(EN+"RunEvent$InitialsIn",false);
        if((schema==null||schema.isEmpty())&&(initialSchema==null||initialSchema.isEmpty()))
            throw new IllegalStateException("Neither LinkIn nor InitialsIn schema is loaded; arrivals unavailable");
        Map<String,Long> kinds=new TreeMap<>();
        Set<String> known=Set.of("Start","LinkIn","InitialsIn","ZeroIn","StaticOwner","MarkRequestsIn","ChangedRequests","InitialAnswersIn","Delivery","Work");
        for(IClass c:snapshot.getClasses())if(c.getName().startsWith(EN+"RunEvent$")) {
            String name=c.getName().substring((EN+"RunEvent$").length());
            if(!known.contains(name))throw new IllegalStateException("Unknown RunEvent schema "+c.getName());
            inc(kinds,name,c.getNumberOfObjects());
        }
        Map<String,Long> counts=new TreeMap<>(),headers=new TreeMap<>(),refPremises=new TreeMap<>();
        HashMapIntObject<ArrivalOwner> owners=new HashMapIntObject<>();
        SetInt facts=new SetInt(),refs=new SetInt(),masks=new SetInt();
        Set<ArrivalPayload> payloads=new HashSet<>();Set<RefRoute> routes=new HashSet<>();
        int[] linkIds=ids(EN+"RunEvent$LinkIn");
        for(int linkId:linkIds) {
            tick();IObject event=snapshot.getObject(linkId),callee=obj(f(event,"callee")),ref=obj(f(event,"ref")),fact=obj(f(event,"added"));
            if(callee==null||ref==null||fact==null)throw new IllegalStateException("Null LinkIn required field");
            if(!cls(ref).equals(ST+"CallerRef"))throw new IllegalStateException("Unknown LinkIn ref "+cls(ref));
            String linkLayer=en(f(event,"linkLayer"));
            if(!linkLayer.equals(en(f(fact,"layer"))))throw new IllegalStateException("LinkIn link/fact layers differ");
            IObject caller=obj(f(ref,"caller")),premise=obj(f(ref,"premise")),call=obj(f(ref,"call"));
            if(caller==null||premise==null||call==null)throw new IllegalStateException("Incomplete CallerRef");
            String callerLayer=en(f(ref,"callerLayer"));int stage=(int)number(f(ref,"stageOrdinal"));
            if(stage<0)throw new IllegalStateException("Negative CallerRef stage");
            RefRoute route=new RefRoute(caller.getObjectId(),premise.getObjectId(),callerLayer,call.getObjectId(),stage);
            routes.add(route);refs.add(ref.getObjectId());facts.add(fact.getObjectId());
            String premiseKind;
            if(cls(premise).equals(AP+"PremiseSet"))premiseKind="ND";
            else if(cls(premise).equals(AP+"InitialAp"))premiseKind=base(obj(f(premise,"base"))).equals("Zero")?"ZERO":"single";
            else throw new IllegalStateException("Unknown CallerRef premise "+cls(premise));
            inc(refPremises,premiseKind,1);
            ArrivalOwner owner=owners.get(callee.getObjectId());
            if(owner==null){owner=new ArrivalOwner();owners.put(callee.getObjectId(),owner);}
            owner.raw++;owner.facts.add(fact.getObjectId());owner.refs.add(ref.getObjectId());
            String factClass=cls(fact);String scope=family(base(obj(f(fact,"base"))));
            if(factClass.equals(AP+"Reach")||scope.equals("Z")) {
                if(!factClass.equals(AP+"Reach")||!scope.equals("Z"))throw new IllegalStateException("Invalid ZERO/Reach incoming fact");
                owner.excluded++;inc(counts,"excludedZEROReach",1);continue;
