    static String json(Object o) {
        if(o==null)return "null";if(o instanceof Number||o instanceof Boolean)return o.toString();
        if(o instanceof Map){List<String> a=new ArrayList<>();for(Map.Entry<?,?> e:((Map<?,?>)o).entrySet())a.add(json(e.getKey().toString())+":"+json(e.getValue()));return "{"+String.join(",",a)+"}";}
        if(o instanceof Iterable){List<String> a=new ArrayList<>();for(Object v:(Iterable<?>)o)a.add(json(v));return "["+String.join(",",a)+"]";}
        String s=o.toString();return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";
    }
    private static boolean bindingRuntimeMatches(String sourceBinding,String runtime) {
        return sourceBinding.matches("(?s).*\"runtime\"\\s*:\\s*\""+runtime+"\".*");
    }
    @Override public IResult execute(IProgressListener progress) throws Exception {
        if(runtime==null||!runtime.matches("[0-9a-f]{40}"))throw new IllegalArgumentException("Full pinned runtime is required");
        for(String label:new String[]{reached,complete,accepted})
            if(label==null||!label.matches("run-[1-9][0-9]*|none"))throw new IllegalArgumentException("Explicit iteration labels are required");
        String sourceBinding=Files.readString(Path.of(binding));
        if(!bindingRuntimeMatches(sourceBinding,runtime))
            throw new IllegalArgumentException("Source binding runtime mismatch");
        listener=progress;result.put("runtime",runtime);result.put("binding",binding);
        result.put("bindingSha256",java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(sourceBinding.getBytes(java.nio.charset.StandardCharsets.UTF_8))));
        result.put("latestReached",reached);result.put("latestComplete",complete);result.put("acceptedForward",accepted);
        result.put("snapshot",snapshot.getSnapshotInfo().getPath());result.put("phase",phase);result.put("retainedRequested",retained);
        result.put("scope","Snapshot memberships, physical metadata indexes and exact literal identity images; not historical processing counts or semantic equality by overlap.");
        switch(phase) {
            case "probe":probe();break;
            case "methods":methods();break;
            case "caches":caches();break;
            case "forms":forms();break;
            case "indexes":indexes();break;
            case "queues":queues();break;
            case "visibility":visibility();break;
            case "owners":owners();break;
            case "deliveries":deliveries();break;
            case "arrivals":arrivals();break;
            case "n2eligibility":n2Eligibility();break;
            case "all":caches();checkpoint("caches");forms();checkpoint("forms");indexes();checkpoint("indexes");visibility();checkpoint("visibility");queues();checkpoint("queues");methods();checkpoint("methods");if(retained)owners();break;
            default:throw new IllegalArgumentException("Unknown phase "+phase);
        }
        result.put("state","COMPLETE");result.put("visited",visited);Files.writeString(Path.of(output),json(result)+"\n");
        return new TextResult("COMPLETE: "+output);
    }
