package compactdiag;

import java.nio.file.*;
import org.eclipse.equinox.app.IApplication;
import org.eclipse.equinox.app.IApplicationContext;
import org.eclipse.mat.query.registry.QueryRegistry;
import org.eclipse.mat.query.registry.QueryDescriptor;
import org.osgi.framework.FrameworkUtil;

/** Actual OSGi query registration control; never opens a snapshot. */
public final class RegistryCheck implements IApplication {
    public Object start(IApplicationContext context) throws Exception {
        String output=System.getProperty("compact.registry.output");
        if(output==null)throw new IllegalStateException("Registry output path required");
        QueryDescriptor query=QueryRegistry.instance().getQuery("compact_memory_census");
        if(query==null)throw new IllegalStateException("compact_memory_census is absent from actual query registry");
        String install=System.getProperty("osgi.install.area");
        String expected=System.getProperty("compact.registry.expectedInstall");
        if(expected==null||!install.equals(expected))throw new IllegalStateException("Wrong install area: "+install);
        String bundle=FrameworkUtil.getBundle(CompactMemoryCensus.class).getSymbolicName();
        if(!bundle.equals("diag.compact.memory.census"))throw new IllegalStateException("Wrong query bundle "+bundle);
        Files.writeString(Path.of(output),"PASS actual OSGi registry; query=compact_memory_census; bundle="+bundle+"; install="+install+"; heapOpened=false\n");
        System.out.println("REGISTRY_CONTROL_PASS no heap opened");
        return IApplication.EXIT_OK;
    }
    public void stop() {}
}

